import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"slides/keyboard-shortcuts.md","filePath":"slides/keyboard-shortcuts.md"}'),c={name:"slides/keyboard-shortcuts.md"};function a(i,t,l,h,n,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Keyboard shortcuts for the slides editor. Mac shortcuts are shown with <code>⌘</code>, Windows/Linux with <code>Ctrl</code>. Press <code>⌘+/</code> (or <code>Ctrl+/</code>) in the editor to open the in-app shortcuts help.</p><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Select all elements on the slide</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Cycle to next element</td><td><code>Tab</code></td></tr><tr><td>Cycle to previous element</td><td><code>Shift+Tab</code></td></tr><tr><td>Clear selection / exit text edit / leave a group</td><td><code>Esc</code></td></tr><tr><td>Enter text edit on selected text element</td><td><code>F2</code> or <code>Enter</code></td></tr><tr><td>Enter text edit and start typing</td><td>Any printable character</td></tr><tr><td>Group selected elements</td><td><code>⌘+Alt+G</code> / <code>Ctrl+Alt+G</code></td></tr><tr><td>Ungroup selected group</td><td><code>⌘+Shift+Alt+G</code> / <code>Ctrl+Shift+Alt+G</code></td></tr></tbody></table><p>Typing a printable character with a single text or shape element selected enters text edit and inserts that character — you don&#39;t have to type it twice.</p><h2 id="slides" tabindex="-1">Slides <a class="header-anchor" href="#slides" aria-label="Permalink to &quot;Slides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>New slide after the current one, same layout</td><td><code>⌘+M</code> / <code>Ctrl+M</code></td></tr><tr><td>Duplicate current slide</td><td><code>⌘+Shift+D</code> / <code>Ctrl+Shift+D</code></td></tr><tr><td>Next slide</td><td><code>Page Down</code></td></tr><tr><td>Previous slide</td><td><code>Page Up</code></td></tr><tr><td>Previous / next slide (thumbnail strip focused)</td><td><code>↑</code> / <code>↓</code></td></tr></tbody></table><p><code>↑</code> / <code>↓</code> only change slides when the thumbnail strip has focus <strong>and</strong> nothing is selected on the canvas — with a selection they nudge the selected elements instead.</p><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> / <code>Ctrl+Shift+Z</code></td></tr><tr><td>Delete selected</td><td><code>Delete</code> / <code>Backspace</code></td></tr><tr><td>Duplicate selected elements (or the current slide, if nothing is selected)</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Nudge selection</td><td>Arrow keys</td></tr><tr><td>Nudge selection (larger step)</td><td><code>Shift+Arrow</code></td></tr></tbody></table><h2 id="clipboard" tabindex="-1">Clipboard <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Clipboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Copy</td><td><code>⌘+C</code> / <code>Ctrl+C</code></td></tr><tr><td>Cut</td><td><code>⌘+X</code> / <code>Ctrl+X</code></td></tr><tr><td>Paste</td><td><code>⌘+V</code> / <code>Ctrl+V</code></td></tr><tr><td>Paste as plain text (while editing text)</td><td><code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code></td></tr></tbody></table><p><code>⌘+Shift+V</code> strips formatting only <em>inside</em> a text box. On the canvas it is an ordinary element paste — the same as <code>⌘+V</code>.</p><h2 id="z-order" tabindex="-1">Z-order <a class="header-anchor" href="#z-order" aria-label="Permalink to &quot;Z-order&quot;">​</a></h2><p>These apply to the selected elements on the canvas. They are ignored while you&#39;re editing text inside a box, so <code>⌘+↑</code> / <code>⌘+↓</code> still move the caret there.</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Bring to front</td><td><code>⌘+Shift+↑</code> / <code>Ctrl+Shift+↑</code></td></tr><tr><td>Send to back</td><td><code>⌘+Shift+↓</code> / <code>Ctrl+Shift+↓</code></td></tr><tr><td>Bring forward</td><td><code>⌘+↑</code> / <code>Ctrl+↑</code></td></tr><tr><td>Send backward</td><td><code>⌘+↓</code> / <code>Ctrl+↓</code></td></tr></tbody></table><h2 id="text-editing" tabindex="-1">Text Editing <a class="header-anchor" href="#text-editing" aria-label="Permalink to &quot;Text Editing&quot;">​</a></h2><p>These apply while editing inside a text box.</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Insert / edit link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Clear formatting</td><td><code>⌘+\\</code> / <code>Ctrl+\\</code></td></tr><tr><td>Align left</td><td><code>⌘+Shift+L</code> / <code>Ctrl+Shift+L</code></td></tr><tr><td>Align center</td><td><code>⌘+Shift+E</code> / <code>Ctrl+Shift+E</code></td></tr><tr><td>Align right</td><td><code>⌘+Shift+R</code> / <code>Ctrl+Shift+R</code></td></tr><tr><td>Align justified</td><td><code>⌘+Shift+J</code> / <code>Ctrl+Shift+J</code></td></tr><tr><td>Indent</td><td><code>⌘+]</code> / <code>Ctrl+]</code></td></tr><tr><td>Outdent</td><td><code>⌘+[</code> / <code>Ctrl+[</code></td></tr></tbody></table><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p>These apply while editing text inside a table cell.</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Next cell</td><td><code>Tab</code></td></tr><tr><td>Previous cell</td><td><code>Shift+Tab</code></td></tr><tr><td>Next / previous cell (at the end / start of the cell&#39;s text)</td><td><code>→</code> / <code>←</code></td></tr></tbody></table><p><code>Tab</code> in the last cell appends a new row and moves into its first cell. <code>Tab</code> never takes you out of the table.</p><h2 id="cropping-an-image" tabindex="-1">Cropping an Image <a class="header-anchor" href="#cropping-an-image" aria-label="Permalink to &quot;Cropping an Image&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Apply the crop</td><td><code>Enter</code></td></tr><tr><td>Cancel the crop</td><td><code>Esc</code></td></tr></tbody></table><p>While crop mode is active every other shortcut is suppressed, so <code>Delete</code> and the arrow keys can&#39;t disturb the image mid-crop.</p><h2 id="present" tabindex="-1">Present <a class="header-anchor" href="#present" aria-label="Permalink to &quot;Present&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Start from current slide</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr><tr><td>Start from first slide</td><td><code>⌘+Shift+Enter</code> / <code>Ctrl+Shift+Enter</code></td></tr><tr><td>Next slide (in present mode)</td><td><code>→</code> / <code>Space</code> / <code>Page Down</code> / <code>N</code> / Click</td></tr><tr><td>Previous slide (in present mode)</td><td><code>←</code> / <code>Backspace</code> / <code>Page Up</code> / <code>P</code></td></tr><tr><td>Jump to the first slide</td><td><code>Home</code></td></tr><tr><td>Jump to the last slide</td><td><code>End</code></td></tr><tr><td>Exit</td><td><code>Esc</code></td></tr></tbody></table><p>While presenting, editor shortcuts are disabled — <code>⌘+Z</code> cannot undo the live deck.</p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Open shortcuts help</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table>',31)])])}const u=e(c,[["render",a]]);export{p as __pageData,u as default};
